DROP TABLE IF EXISTS `attedance_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attedance_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL,
  `token_id` bigint DEFAULT NULL,
  `status` enum('hadir','telat','alfa','sakit','izin','belum_absen') DEFAULT 'belum_absen',
  `captured_ip` varchar(45) DEFAULT NULL,
  `clock_in_time` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_daily` (`user_id`,(cast(`clock_in_time` as date))),
  KEY `idx_attedance_logs_user_id` (`user_id`),
  KEY `idx_attedance_logs_token_id` (`token_id`),
  CONSTRAINT `attedance_logs_ibfk_2` FOREIGN KEY (`token_id`) REFERENCES `attedance_tokens` (`id`),
  CONSTRAINT `fk_attedance_logs_token` FOREIGN KEY (`token_id`) REFERENCES `attedance_tokens` (`id`),
  CONSTRAINT `fk_users_attedance_logs` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6465 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
